#!/usr/bin/env ruby
require_relative 'lib/era_zero_validation'
require_relative 'lib/era_zero_compound_conventions'
V=EraZeroValidation
d=V.load_yaml('lexicon/compound_dictionary.yaml');reviews=V.load_yaml('reviews/gate4b_high_frequency_compounds_scored_candidates.yaml')
before=V.fingerprint(d['entries']);prior=d['entries'].map{|e|e['compound_id']}
fetch=lambda{|key|d['entries'].find{|e|e.dig('conventional_meaning','sense_key')==key}||raise('Missing spatial dependency '+key)}
exterior=fetch.call('physical_region_exterior');interior=fetch.call('physical_region_interior')
definition='Completion of one physical entry event in which the same material participant displaces across the boundary of the same contextual physical region, from its exterior before the crossing to its interior at culmination. Both spatial phases use the same region, relevant participant extent and spatial frame. The exterior and interior relations are internal event phases, not simultaneous assertions or independent claims about speech time. The mover displacement constitutes this crossing; an unrelated movement plus a location change, a changed region interpretation or stationary enclosure by an expanding region is insufficient. Boundary contact may occur during the transition. No prescribed route, locomotion manner, conscious intention, permission, ownership, custody or continued presence after culmination is asserted.'
excludes=['Being inside throughout, approaching without crossing or arrival at an exterior doorstep','Different participants, regions, frames or extent criteria in the two phases','Stationary enclosure or a redefined boundary without the required mover displacement','Entry of data, registration for a competition or other nonspatial senses','Completion, past tense and runtime state treated as interchangeable']
actor_paths=[['q-0-before','s-bearer'],['q-1-after','s-bearer'],['s-actor']];region_paths=[['q-0-before','s-region'],['q-1-after','s-region'],['s-region']]
payload={'architecture_version'=>'1.0','semantic_head'=>'h','nodes'=>[{'node_id'=>'q-0-before','kind'=>'compound_ref','compound_id'=>exterior['compound_id'],'definition_version'=>'1.0.0'},{'node_id'=>'q-1-after','kind'=>'compound_ref','compound_id'=>interior['compound_id'],'definition_version'=>'1.0.0'},{'node_id'=>'s-actor','kind'=>'slot','slot_name'=>'entering_participant','slot_type'=>'entity'},{'node_id'=>'s-region','kind'=>'slot','slot_name'=>'entered_region','slot_type'=>'entity'},{'node_id'=>'h','kind'=>'root','root_id'=>'MOV:120'}],'edges'=>[{'type'=>'qualifies','from'=>'q-0-before','to'=>'h'},{'type'=>'qualifies','from'=>'q-1-after','to'=>'h'},{'type'=>'fills_role','from'=>'s-actor','to'=>'h','role'=>'actor'},{'type'=>'fills_role','from'=>'s-region','to'=>'h','role'=>'environment'}],'binding_constraints'=>[{'relation'=>'same_argument','slot_paths'=>actor_paths},{'relation'=>'same_argument','slot_paths'=>region_paths}],'lexical_constraints'=>['The nested exterior state is the pre-crossing phase and the nested interior state is the culmination phase of this same displacement event.','The actual mover is the same material bearer in both spatial relations; the region anchors the same shared frame throughout.','No nested spatial state has an independent runtime ending or speech-time assertion.'],'conventional_meaning'=>{'profile'=>'EZLEX-1','sense_key'=>'completed_physical_entry','sound_code'=>29,'added_definition'=>definition,'excludes'=>excludes}}
digest=V.fingerprint(payload);id="CMP:#{digest[0,24]}"
entry=payload.merge('compound_id'=>id,'content_digest'=>digest,'definition_version'=>'1.0.0','status'=>'approved','approval_date'=>'2026-11-04','display_title'=>'completed physical entry','english_glosses'=>['completed physical entry'],'invariant_definition'=>definition,'boundaries'=>{'includes'=>definition,'excludes'=>excludes.join('; ')},'collision_audit'=>'reviews/spatial_entry_foundation.md; displacement plus version-pinned exterior/interior phases requires explicit same-event and boundary-crossing convention.','confidence'=>'high','approval_record'=>'migrations/physical_entry_2026_11_04.yaml','approval_basis'=>'Author semantic review under the user-directed translator completion goal; not independent linguistic validation.','examples'=>{'ordinary'=>'Nora entered the archive.','technical'=>'Same-argument constraints preserve mover and region across both internal phases and the displacement head.','future_compound'=>'Reuse this exact event under permission, possibility and manner-specific entry.','counterexample'=>'Nora arrives at the doorstep but remains outside.'},'serialization'=>{'canonical_format'=>'EZC-JSON-1','content_digest'=>digest})
old=d['entries'].find{|e|e['compound_id']==id};raise 'Existing entry changed' if old&&old!=entry;d['entries']<<entry unless old
unless reviews['reviews'].any?{|r|r['compound_id']==id}
 candidates=[['explicit_entry_convention','Preserve both spatial phases, same participant and same region, linked to one completed displacement.',[9,10,10,9,9,10,8,10],'winner'],['arrival_only','Arrival at an exterior target does not entail entry.',[9,10,10,2,3,5,4,5],'rejected'],['state_conjunction','Exterior and interior without phase/event linkage lose the transition.',[5,5,6,2,3,4,3,4],'rejected']].map{|name,reason,scores,decision|{'candidate_id'=>name,'direction'=>reason,'scores'=>V::SCORE_KEYS.zip(scores).to_h,'total'=>scores.sum,'decision'=>decision}}
 candidates[0]['graph']=payload.slice('semantic_head','nodes','edges','conventional_meaning','binding_constraints')
 reviews['reviews']<<{'compound_id'=>id,'display_title'=>entry['display_title'],'current_choice_reason'=>'reviews/spatial_entry_foundation.md; author judgments, not independent validation.','candidates'=>candidates,'recommendation'=>'approve explicit_entry_convention','confidence'=>'high'}
end
EraZeroCompoundConventions.validate!(d['entries']);d['entries'].sort_by!{|e|e['compound_id']};d['metadata']['entry_count']=d['entries'].length
V.write('lexicon/compound_dictionary.yaml',YAML.dump(d));V.write('reviews/gate4b_high_frequency_compounds_scored_candidates.yaml',YAML.dump(reviews))
migration='migrations/physical_entry_2026_11_04.yaml';V.write(migration,YAML.dump({'authority'=>'User-directed translator-completion goal','review'=>'reviews/spatial_entry_foundation.md','before_dictionary_fingerprint'=>before,'previous_compound_ids'=>prior,'added_compound_id'=>id,'dependencies'=>[exterior['compound_id'],interior['compound_id']],'new_convention_code'=>29,'existing_meanings_changed'=>false})) unless File.exist?(File.join(V::ROOT,migration))
V.write('pages/physical_entry.mjs',"export const PHYSICAL_ENTRY = #{JSON.generate({requiredInterpretation:'physical_entry',pattern:'entered',negativePattern:'did not enter',predicate:id,key:'completed_physical_entry',wording:'entered',role:'actor',targetRole:'environment',speechTime:'before',compoundSlots:{actor:actor_paths,environment:region_paths},semanticNote:definition})};\n")
puts id
